import{_ as t,o,c as r,ag as a}from"./chunks/framework.BuUvxvtQ.js";const p=JSON.parse('{"title":"Custom Weather Sources (Pro)","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/custom-weather-sources.md","filePath":"web-app/custom-weather-sources.md"}'),d={name:"web-app/custom-weather-sources.md"};function s(i,e,c,n,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="custom-weather-sources-pro" tabindex="-1">Custom Weather Sources (Pro) <a class="header-anchor" href="#custom-weather-sources-pro" aria-label="Permalink to &quot;Custom Weather Sources (Pro)&quot;">​</a></h1><p>Pro users can add their own weather data sources so recommendations draw from data you trust or control — for example a private weather station feed or a paid provider not built into Sky Style.</p><p>This is separate from the <a href="./how-it-works.html#source-picker">source picker</a>, which lets you choose among the built-in sources.</p><h2 id="how-custom-sources-work" tabindex="-1">How custom sources work <a class="header-anchor" href="#how-custom-sources-work" aria-label="Permalink to &quot;How custom sources work&quot;">​</a></h2><ol><li>You add one or more source <strong>URLs</strong> that return weather data as JSON.</li><li>Sky Style fetches each URL alongside (or instead of) the built-in sources.</li><li>When multiple custom sources return data, the numeric fields are averaged and all readings are passed to the AI as context (see <a href="./how-it-works.html#multi-source-aggregation">Multi-source aggregation</a>).</li><li>Custom source readings are marked with an accuracy of <code>Medium</code> (unverified accuracy).</li></ol><p>You can choose a <strong>source mode</strong>:</p><ul><li><strong>Built-in</strong> — use only Sky Style&#39;s built-in sources (custom sources ignored).</li><li><strong>Custom</strong> — use only your custom sources. If none return data, Sky Style falls back to built-in sources automatically.</li><li><strong>Both</strong> — combine built-in and custom sources for maximum coverage.</li></ul><h2 id="url-requirements" tabindex="-1">URL requirements <a class="header-anchor" href="#url-requirements" aria-label="Permalink to &quot;URL requirements&quot;">​</a></h2><p>Custom source URLs must satisfy these rules, enforced to prevent <a href="https://owasp.org/www-community/attacks/Server_Side_Request_Forgery" target="_blank" rel="noreferrer">SSRF</a> attacks:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Detail</th></tr></thead><tbody><tr><td><strong>HTTPS only</strong></td><td>The URL must use the <code>https://</code> scheme.</td></tr><tr><td><strong>Default port</strong></td><td>The URL must use the default HTTPS port (443). Explicit non-default ports are rejected.</td></tr><tr><td><strong>No credentials</strong></td><td>The URL must not contain a username or password (<code>https://user:pass@host</code> is rejected).</td></tr><tr><td><strong>Public host</strong></td><td>The hostname must resolve to a public address. Private, internal, link-local, and metadata endpoints are blocked (see below).</td></tr></tbody></table><h3 id="blocked-host-types" tabindex="-1">Blocked host types <a class="header-anchor" href="#blocked-host-types" aria-label="Permalink to &quot;Blocked host types&quot;">​</a></h3><p>The following are rejected to protect the server:</p><ul><li><code>localhost</code>, <code>127.0.0.1</code>, <code>0.0.0.0</code>, <code>::1</code></li><li>Private IPv4 ranges: <code>10.0.0.0/8</code>, <code>192.168.0.0/16</code>, <code>172.16.0.0/12</code></li><li>Link-local IPv4: <code>169.254.0.0/16</code> (this includes the cloud metadata endpoint <code>169.254.169.254</code>)</li><li>IPv6 private and link-local ranges</li><li>Hostnames ending in <code>.local</code>, <code>.internal</code>, or <code>.localhost</code></li><li>Multicast addresses</li></ul><div class="warning custom-block"><p class="custom-block-title">DNS resolution</p><p>The hostname is resolved and checked at request time. A hostname that resolves to a private or internal IP will be rejected, even if it looks public.</p></div><h2 id="expected-data-shape" tabindex="-1">Expected data shape <a class="header-anchor" href="#expected-data-shape" aria-label="Permalink to &quot;Expected data shape&quot;">​</a></h2><p>Your custom source should return JSON that Sky Style can map to its weather data structure. A best-effort parse is applied — the most important fields are:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>temp</code></td><td>number</td><td>Temperature (Celsius).</td></tr><tr><td><code>feelsLike</code></td><td>number</td><td>Apparent temperature.</td></tr><tr><td><code>humidity</code></td><td>number</td><td>Relative humidity (0–100).</td></tr><tr><td><code>windSpeed</code></td><td>number</td><td>Wind speed (km/h).</td></tr><tr><td><code>windDir</code></td><td>string</td><td>Cardinal wind direction.</td></tr><tr><td><code>description</code></td><td>string</td><td>Human-readable conditions.</td></tr><tr><td><code>rainChance</code></td><td>number</td><td>Precipitation probability (0–100).</td></tr><tr><td><code>uvIndex</code></td><td>number</td><td>UV index.</td></tr></tbody></table><p>Sources that return an <code>hourly</code> array (each entry with <code>time</code>, <code>temp</code>, <code>description</code>, <code>rainChance</code>, <code>windSpeed</code>) also feed the Weather Planning panel.</p><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h2><p>Custom source data is cached for <strong>10 minutes</strong> per location to avoid excessive calls to your endpoint.</p><h2 id="provider-key-passthrough" tabindex="-1">Provider key passthrough <a class="header-anchor" href="#provider-key-passthrough" aria-label="Permalink to &quot;Provider key passthrough&quot;">​</a></h2><p>Some built-in providers can also be used as custom sources by passing your own API key:</p><table tabindex="0"><thead><tr><th>Custom source type</th><th>Uses your key for</th></tr></thead><tbody><tr><td>WeatherAPI.com</td><td>The <code>weatherapi.com</code> endpoint</td></tr><tr><td>Visual Crossing</td><td>The Visual Crossing endpoint</td></tr><tr><td>Pirate Weather</td><td>The Pirate Weather endpoint</td></tr><tr><td>OpenWeatherMap</td><td>The OpenWeather endpoint</td></tr></tbody></table><p>This lets you supply a key Sky Style&#39;s deployment doesn&#39;t have configured, while reusing the built-in parsing logic.</p>',24)])])}const m=t(d,[["render",s]]);export{p as __pageData,m as default};
